import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    book = {}  # id -> dict with side, price, qty, arrival, active
    seq = 0

    for order in orders:
        seq += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                sp, sarr, soid = sell_heap[0]
                sinfo = book.get(soid)
                if sinfo is None or not sinfo['active'] or sinfo['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and sp > price:
                    break
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, soid, sp, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] == 0:
                    sinfo['active'] = False
                    heapq.heappop(sell_heap)

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'arrival': seq, 'active': True}
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # sell
            while remaining > 0 and buy_heap:
                bp_neg, barr, boid = buy_heap[0]
                bp = -bp_neg
                binfo = book.get(boid)
                if binfo is None or not binfo['active'] or binfo['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and bp < price:
                    break
                trade_qty = min(remaining, binfo['qty'])
                trades.append([boid, oid, bp, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] == 0:
                    binfo['active'] = False
                    heapq.heappop(buy_heap)

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'arrival': seq, 'active': True}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

